const SCHEME_ROW_H = 44, SCHEME_COL_W = 290, SCHEME_NODE_W = 230;
const PACK_COLS = 4, PACK_CHIP_W = 62, PACK_CHIP_H = 26, PACK_HEAD = 26, PACK_PAD = 10;
function packBoxSize(node){
  const rows = Math.ceil(node.packs.length / PACK_COLS);
  return { w: PACK_PAD*2 + PACK_COLS*PACK_CHIP_W,
           h: PACK_HEAD + PACK_PAD + rows*PACK_CHIP_H + 6 };
}
let _schemeIdSeq = 0;
function assignSchemeIds(node){
  node._id = 'n' + (_schemeIdSeq++);
  (node.children || []).forEach(assignSchemeIds);
}
function findSchemeNode(node, id){
  if (node._id === id) return node;
  for (const ch of (node.children || [])) {
    const f = findSchemeNode(ch, id);
    if (f) return f;
  }
  return null;
}
function schemeLayout(node, depth, yRef){
  node._depth = depth;
  if (node.kind === "packbox") {
    const s = packBoxSize(node);
    node._w = s.w; node._h = s.h;
  } else {
    const lines = node.label.split("\n").length;
    node._h = Math.max(SCHEME_ROW_H, lines * 16 + 20);
    node._w = SCHEME_NODE_W;
  }
  const kids = node.collapsed ? [] : (node.children || []);
  if (!kids.length) {
    node._y = yRef.y;
    yRef.y += node._h + 9;
  } else {
    const firstY = yRef.y;
    kids.forEach(ch => schemeLayout(ch, depth + 1, yRef));
    const lastChild = kids[kids.length - 1];
    node._y = (firstY + (lastChild._y + lastChild._h)) / 2 - node._h / 2;
  }
  node._x = depth * SCHEME_COL_W;
  return node;
}
function schemeEsc(s){ return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
function packBoxSVG(node){
  const x = node._x, y = node._y, w = node._w;
  let h = '<g class="xp-scheme-node packbox">';
  h += '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + node._h + '"></rect>';
  h += '<text class="pb-title" x="' + (x + PACK_PAD) + '" y="' + (y + 17) + '">' + schemeEsc(node.title) + '</text>';
  node.packs.forEach((p, k) => {
    const col = k % PACK_COLS, row = Math.floor(k / PACK_COLS);
    const cx = x + PACK_PAD + col*PACK_CHIP_W, cy = y + PACK_HEAD + PACK_PAD/2 + row*PACK_CHIP_H;
    const chipCls = p.shared ? 'pb-chip shared' : 'pb-chip';
    h += '<g class="' + chipCls + '"><title>' + schemeEsc(
        p.shared ? ('PACK ' + p.id + ' \u2014 \u0442\u0430\u043a\u0436\u0435 \u0432: ' + p.also)
                 : ('PACK ' + p.id + ' \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u0434\u0435\u0441\u044c')) + '</title>';
    h += '<rect x="' + cx + '" y="' + cy + '" width="' + (PACK_CHIP_W-6) + '" height="' + (PACK_CHIP_H-6) + '" rx="4"></rect>';
    h += '<text x="' + (cx + (PACK_CHIP_W-6)/2) + '" y="' + (cy + 14) + '" text-anchor="middle">' + p.id + '</text>';
    if (p.shared) h += '<circle cx="' + (cx + PACK_CHIP_W - 10) + '" cy="' + (cy + 5) + '" r="3.2"></circle>';
    h += '</g>';
  });
  h += '</g>';
  return h;
}
function schemeNodeSVG(node){
  if (node.kind === "packbox") return packBoxSVG(node);
  const cls = "xp-scheme-node" + (node.kind ? " " + node.kind : "")
            + (node.children && node.children.length ? " has-kids" : "");
  const lines = node.label.split("\n");
  const textY = node._y + node._h/2 - (lines.length-1)*8;
  const boxW = node._w || SCHEME_NODE_W;
  const linkAttr = node.link ? ' data-scheme-link="' + node.link.replace(/"/g,'&quot;') + '"' : '';
  let html = '<g class="' + cls + '"' + linkAttr + '>';
  html += '<rect x="' + node._x + '" y="' + node._y + '" width="' + boxW + '" height="' + node._h + '"></rect>';
  lines.forEach((ln, i) => {
    html += '<text x="' + (node._x + 12) + '" y="' + (textY + i*16 + 5) + '">' + schemeEsc(ln) + '</text>';
  });
  if (node.link) {
    html += '<text x="' + (node._x + boxW - 10) + '" y="' + (node._y + node._h - 8) + '" text-anchor="end" style="font-size:9px; fill:#1955c7; font-style:italic;">\u043e\u0442\u043a\u0440\u044b\u0442\u044c \u2192</text>';
  }
  if (node.children && node.children.length) {
    const n = node.children.length;
    const bx = node._x + boxW - 15, by = node._y + node._h - 15;
    html += '<g class="pb-toggle" data-scheme-toggle="' + node._id + '"><title>' +
      (node.collapsed ? '\u041f\u043e\u043a\u0430\u0437\u0430\u0442\u044c' : '\u0421\u0432\u0435\u0440\u043d\u0443\u0442\u044c') + '</title>' +
      '<circle cx="' + bx + '" cy="' + by + '" r="9"></circle>' +
      '<text x="' + bx + '" y="' + (by + 4) + '" text-anchor="middle">' + (node.collapsed ? '+' : '\u2212') + '</text></g>';
  }
  html += '</g>';
  (node.collapsed ? [] : (node.children || [])).forEach(ch => {
    const x1 = node._x + boxW, y1 = node._y + node._h/2;
    const x2 = ch._x, y2 = ch._y + ch._h/2;
    const mx = (x1 + x2) / 2;
    const linkCls = ch.kind === "tag" ? "xp-scheme-link tag-link" : "xp-scheme-link";
    html += '<path class="' + linkCls + '" d="M ' + x1 + ' ' + y1 + ' C ' + mx + ' ' + y1 + ', ' + mx + ' ' + y2 + ', ' + x2 + ' ' + y2 + '"></path>';
    html += schemeNodeSVG(ch);
  });
  return html;
}
function renderSchemeTree(){
  if (ACCOUNTS_TREE._id === undefined) { _schemeIdSeq = 0; assignSchemeIds(ACCOUNTS_TREE); }
  const yRef = { y: 20 };
  schemeLayout(ACCOUNTS_TREE, 0, yRef);
  const totalH = yRef.y + 20;
  const totalW = (maxDepth(ACCOUNTS_TREE) + 1) * SCHEME_COL_W + 40;
  const svg = '<svg width="' + totalW + '" height="' + totalH + '" xmlns="http://www.w3.org/2000/svg">' + schemeNodeSVG(ACCOUNTS_TREE) + '</svg>';
  document.getElementById('xp-scheme-canvas').innerHTML = svg;
  document.querySelectorAll('[data-scheme-toggle]').forEach(g => {
    g.addEventListener('click', (e) => {
      e.stopPropagation();
      const n = findSchemeNode(ACCOUNTS_TREE, g.getAttribute('data-scheme-toggle'));
      if (!n) return;
      n.collapsed = !n.collapsed;
      const z = schemeZoom, px = schemePanX, py = schemePanY;
      renderSchemeTree();
      schemeZoom = z; schemePanX = px; schemePanY = py;
      applySchemeTransform();
    });
  });
  document.querySelectorAll('[data-scheme-link]').forEach(g => {
    g.addEventListener('click', (e) => {
      e.stopPropagation();
      const acctName = g.getAttribute('data-scheme-link');
      closeSchemeWindow();
      desktopIcon.classList.add('selected');
      openWindow();
      goAccountDetail(acctName);
    });
  });
}
function maxDepth(node){
  const kids = node.collapsed ? [] : (node.children || []);
  if (!kids.length) return node._depth + (node.kind === "packbox" ? 1 : 0);
  return Math.max(...kids.map(maxDepth));
}

let schemeZoom = 1, schemePanX = 40, schemePanY = 20;
function applySchemeTransform(){
  document.getElementById('xp-scheme-canvas').style.transform = 'translate(' + schemePanX + 'px,' + schemePanY + 'px) scale(' + schemeZoom + ')';
  document.getElementById('xp-scheme-zoom-level').textContent = Math.round(schemeZoom * 100) + '%';
}
function schemeZoomBy(factor){
  schemeZoom = Math.min(2.5, Math.max(0.25, schemeZoom * factor));
  applySchemeTransform();
}
function schemeResetView(){
  schemeZoom = 1; schemePanX = 40; schemePanY = 20;
  applySchemeTransform();
}

function openSchemeWindow(){
  renderSchemeTree();
  schemeResetView();
  document.getElementById('xp-scheme-window').classList.add('open');
  document.getElementById('xp-desktop-scheme-icon').classList.add('selected');
  document.getElementById('xp-taskbar-scheme').style.display = 'none';
}
function closeSchemeWindow(){
  document.getElementById('xp-scheme-window').classList.remove('open');
  document.getElementById('xp-scheme-window').classList.remove('maximized');
  document.getElementById('xp-desktop-scheme-icon').classList.remove('selected');
  document.getElementById('xp-taskbar-scheme').style.display = 'none';
}
function minimizeSchemeWindow(){
  document.getElementById('xp-scheme-window').classList.remove('open');
  document.getElementById('xp-taskbar-scheme').style.display = 'flex';
}
function restoreSchemeWindow(){
  document.getElementById('xp-scheme-window').classList.add('open');
  document.getElementById('xp-taskbar-scheme').style.display = 'none';
}

document.getElementById('xp-desktop-scheme-icon').addEventListener('click', () => {
  document.getElementById('xp-desktop-scheme-icon').classList.add('selected');
  openSchemeWindow();
});
document.getElementById('xp-scheme-close').addEventListener('click', closeSchemeWindow);
document.getElementById('xp-scheme-minimize').addEventListener('click', minimizeSchemeWindow);
document.getElementById('xp-scheme-maximize').addEventListener('click', () => {
  document.getElementById('xp-scheme-window').classList.toggle('maximized');
});
document.getElementById('xp-taskbar-scheme').addEventListener('click', () => {
  const win = document.getElementById('xp-scheme-window');
  if (win.classList.contains('open')) { minimizeSchemeWindow(); } else { restoreSchemeWindow(); }
});
document.getElementById('xp-scheme-zoom-in').addEventListener('click', () => schemeZoomBy(1.12));
document.getElementById('xp-scheme-zoom-out').addEventListener('click', () => schemeZoomBy(1/1.12));
document.getElementById('xp-scheme-zoom-reset').addEventListener('click', schemeResetView);

const schemeWrap = document.getElementById('xp-scheme-canvas-wrap');
const schemeCanvasEl = document.getElementById('xp-scheme-canvas');
let schemeWheelTimer = null;
schemeWrap.addEventListener('wheel', (e) => {
  e.preventDefault();
  schemeZoomBy(e.deltaY < 0 ? 1.045 : 1/1.045);
}, { passive: false });

let schemeDragging = false, schemeDragStartX = 0, schemeDragStartY = 0, schemePanStartX = 0, schemePanStartY = 0;
schemeWrap.addEventListener('mousedown', (e) => {
  schemeDragging = true;
  schemeWrap.classList.add('dragging');
  schemeCanvasEl.classList.add('no-transition');
  schemeDragStartX = e.clientX; schemeDragStartY = e.clientY;
  schemePanStartX = schemePanX; schemePanStartY = schemePanY;
});
window.addEventListener('mousemove', (e) => {
  if (!schemeDragging) return;
  schemePanX = schemePanStartX + (e.clientX - schemeDragStartX);
  schemePanY = schemePanStartY + (e.clientY - schemeDragStartY);
  applySchemeTransform();
});
window.addEventListener('mouseup', () => {
  schemeDragging = false;
  schemeWrap.classList.remove('dragging');
  schemeCanvasEl.classList.remove('no-transition');
});
